#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

typedef struct {
    int to;
    int next;
} Edge;

typedef struct {
    int head[MAXN];
    Edge edges[2 * MAXN];
    int edge_cnt;
    int n;
} Tree;

void init_tree(Tree *t, int n) {
    t->n = n;
    t->edge_cnt = 0;
    for (int i = 1; i <= n; i++) {
        t->head[i] = -1;
    }
}

void add_edge(Tree *t, int u, int v) {
    t->edges[t->edge_cnt].to = v;
    t->edges[t->edge_cnt].next = t->head[u];
    t->head[u] = t->edge_cnt++;

    t->edges[t->edge_cnt].to = u;
    t->edges[t->edge_cnt].next = t->head[v];
    t->head[v] = t->edge_cnt++;
}

int queue[MAXN];
int dist[MAXN];
int parent[MAXN];

int bfs(Tree *t, int start, int get_path) {
    for (int i = 1; i <= t->n; i++) {
        dist[i] = -1;
        if (get_path) parent[i] = 0;
    }

    int head = 0, tail = 0;
    queue[tail++] = start;
    dist[start] = 0;

    int farthest = start;

    while (head < tail) {
        int u = queue[head++];
        if (dist[u] > dist[farthest]) {
            farthest = u;
        }

        for (int e = t->head[u]; e != -1; e = t->edges[e].next) {
            int v = t->edges[e].to;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (get_path) parent[v] = u;
                queue[tail++] = v;
            }
        }
    }

    return farthest;
}

int find_center(Tree *t) {
    int u = bfs(t, 1, 0);
    int v = bfs(t, u, 1);

    int path_len = dist[v];
    int steps = path_len / 2;

    int curr = v;
    for (int i = 0; i < steps; i++) {
        curr = parent[curr];
    }

    return curr;
}

Tree circle, square;

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    init_tree(&circle, n);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(&circle, u, v);
    }

    init_tree(&square, m);
    for (int i = 0; i < m - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(&square, u, v);
    }

    int c1 = find_center(&circle);
    int c2 = find_center(&square);

    printf("%d %d\n", c1, c2);

    return 0;
}
